def solve(clue):
    F = fractions.Fraction
    a, b = clue.split('/')
    t0 = F(int(a), int(b))

    def rec(t, start, depth):
        p, q = t.numerator, t.denominator
        if p == 1 and q > start:
            return [q]
        if depth <= 1:
            return None
        d0 = max(start + 1, -(-q // p))
        for d in range(d0, d0 + 50):
            r = t - F(1, d)
            if r.numerator <= 0:
                continue
            sub = rec(r, d, depth - 1)
            if sub:
                return [d] + sub
        return None

    for depth in (2, 3):
        res = rec(t0, 1, depth)
        if res and len(res) >= 2:
            return ' '.join(str(x) for x in res)
    t, out = t0, []
    while t.numerator > 0:
        d = -(-t.denominator // t.numerator)
        out.append(d)
        t -= F(1, d)
    return ' '.join(str(x) for x in out)

